function [wheel_axes, gimbal_axes, spin_axes] = rotor_mounting()
%ROTOR_MOUNTING  How the rotors are mounted: three wheels on the body axes (row i the i-th spin axis); a pyramid's four gimbal axes, 54.7
%   deg from +Z (0.8165, 0.5774), and its rotors' spin axes at the zero gimbal angle.
%   returns wheel_axes: real[1][3][3] (passed a plain number)
%   returns gimbal_axes: real[1][3][4] (passed a plain number)
%   returns spin_axes: real[1][3][4] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    wheel_axes = zeros(3, 3);
    gimbal_axes = zeros(4, 3);
    spin_axes = zeros(4, 3);
    wheel_axes = [([1; 0; 0]).'; ([0; 1; 0]).'; ([0; 0; 1]).'];
    gimbal_axes = [([0.8165; 0; 0.5774]).'; ([0; 0.8165; 0.5774]).'; ([(-(0.8165)); 0; 0.5774]).'; ([0; (-(0.8165)); 0.5774]).'];
    spin_axes = [([0; 1; 0]).'; ([(-(1)); 0; 0]).'; ([0; (-(1)); 0]).'; ([1; 0; 0]).'];
end
